// Briefing plugin — the UPKEEP section.
//
// Contract: 05_daily-briefing/docs/briefing-plugin-spec.md
// Design and the reason behind every filter: 10_error-handler/docs/upkeep-tasks-spec.md
//
// PLAIN TEXT ONLY — never HTML. The briefing escapes centrally, and error text is
// exactly the kind of string that carries angle brackets. One unescaped '<' fails
// the whole sendMessage and the morning message never arrives.

// ---- tuning, all read-side on purpose -------------------------------------
// 010 only labels and counts; every policy decision lives here, so tuning never
// means editing the error path.
const THRESHOLD    = 3;      // identical occurrences before a signature is a defect
// EVERY row is tappable — each one is a thing you either did or handed to someone.
// The ceiling is a blast guard, not a display limit: each action is its own Telegram
// message, and the section's text also competes for the 4096-char cap on the main
// one. Fifteen is well above the real list (8) and well below anything that breaks
// the morning. Overflow is REPORTED, never silent.
const MAX_ITEMS    = 15;
const SIG_CHARS    = 46;
const CB_LIMIT     = 60;     // Telegram caps callback_data at 64 BYTES and rejects the
                             // entire keyboard if one button is over
const COMMITMENT   = 'self::code-health';

// Tier gate — root CLAUDE.md § User tiers. 'off' | 'fix' | 'report'
//   off    text only, no buttons. The default for anyone who has not chosen.
//   fix    ✅ Done / 🤖 Assign  — a reader who edits these workflows (T3)
//   report NOT BUILT. See the spec § Beyond.
// This is not a permission check. Setting 'fix' on a box whose owner does not code
// grants nothing — it just puts a useless button on a message.
const ACTION_MODE = 'fix';

const input  = $('Called').first().json;
const parsed = Date.parse(String(input.date || '').slice(0, 10) + 'T00:00:00');
const nowTs  = Number.isFinite(parsed) ? parsed : Date.now();

const lower = (v) => String(v ?? '').trim().toLowerCase();
const ts    = (v) => { const n = Date.parse(String(v || '')); return Number.isFinite(n) ? n : null; };
const dayOf = (n) => new Date(n).toISOString().slice(0, 10);

const failures = $('Get Failures').all().map((i) => i.json).filter((r) => r && r.fingerprint);
const tasks    = $('Get Tasks').all().map((i) => i.json).filter((r) => r && r.task_id);
const byId     = new Map(tasks.map((t) => [String(t.task_id).trim(), t]));

// ---- OBSERVED — grouped from the failure log, never counted into a column --
// Counting at write time would race: failures arrive in bursts (four in eleven
// minutes, in the case this was built for) and Sheets read-then-write is not
// atomic, so two handlers both read 3 and both write 4. Worse, an upsert could
// reset a status a human set. Events are counted at read; state is stored.
const groups = new Map();
for (const r of failures) {
  const fp = String(r.fingerprint).trim();
  if (!fp) continue;
  let g = groups.get(fp);
  if (!g) groups.set(fp, (g = { fp, n: 0, first: null, last: null, row: r }));
  g.n++;
  const t = ts(r.timestamp);
  if (t === null) continue;
  if (g.first === null || t < g.first) g.first = t;
  if (g.last === null || t > g.last) { g.last = t; g.row = r; }
}

const observed = [];
for (const g of groups.values()) {
  if (g.n < THRESHOLD) continue;

  // RECURRENCE PROMOTES, IT NEVER DEMOTES.
  // Repeating identically is not evidence of a defect — the two largest recurring
  // signatures on this instance are rate limits and task-runner timeouts, which is
  // precisely what retry exists for. Recurrence can lift an already-non-retryable
  // error to "defect"; the classifier keeps the veto on everything else.
  // Empty / unknown counts as retryable, so an unclassifiable row is never elevated.
  if (lower(g.row.is_retryable) !== 'false') continue;

  const taskId = COMMITMENT + '@' + g.fp;
  const t  = byId.get(taskId);
  const st = lower(t && t.status);

  if (st === 'wont_fix') continue;

  // Optimistic hide, self-auditing. 'done' drops the row — but a NEW occurrence
  // after closed_at is direct proof the fix did not work, so it comes back on its
  // own. No reopen branch, no second book to check against.
  let reopened = false;
  if (st === 'done') {
    const closed = ts(t.closed_at);
    if (closed === null || g.last === null || g.last <= closed) continue;
    reopened = true;
  }
  observed.push({ g, taskId, reopened, status: st });
}
observed.sort((a, b) => (b.g.last || 0) - (a.g.last || 0));

// 'assigned' stays on the list and says so. Nothing acts on an assignment yet, so a
// row sits at ⏳ until it is closed by hand — which is the honest display, because it
// is genuinely not done. Presence is the default; absence is the achievement.
const stateSuffix = (st) => (st === 'assigned' ? ' · ⏳ assigned'
  : st === 'failed' ? ' · ⚠️ failed' : '');

// Cutting the signature can bisect a normalisation placeholder and leave a bare
// '<' ("...item at index <n" ). The briefing's esc() makes that safe rather than
// dangerous, but it still reads as broken, so trim back to the last clean break.
const clipSig = (s) => {
  let out = String(s || '').slice(0, SIG_CHARS);
  const lt = out.lastIndexOf('<');
  if (lt > -1 && !out.slice(lt).includes('>')) out = out.slice(0, lt);
  return out.trim();
};

const observedLine = ({ g, reopened, status }) => {
  const wf   = String(g.row.workflow_name || 'unknown').replace(/\.n8n$/, '');
  const node = String(g.row.failed_node || '?');
  const sig  = clipSig(g.row.error_signature);
  const since = g.first === null ? 'unknown' : dayOf(g.first);
  return wf + ' · ' + node + ' · ' + sig + ' · ' + g.n + '× since ' + since
    + (reopened ? ' · ⚠️ recurred after being marked fixed' : '')
    + stateSuffix(status);
};

// ---- DECLARED — hand-typed obligations, the Open thread blocks -------------
// No parser reads CLAUDE.md. That file is prose written for an LLM; turning it
// into a data source would put format constraints on the one file loaded into
// every session. The block is the explanation, the row is the occurrence.
const declared = tasks
  .filter((t) => lower(t.commitment_id) === COMMITMENT && lower(t.source) === 'declared')
  .filter((t) => !['done', 'wont_fix', 'cancelled'].includes(lower(t.status)))
  .sort((a, b) => String(a.task_id).localeCompare(String(b.task_id)));

const declaredLine = (t) => {
  const txt = String(t.action || t.notes || String(t.task_id).split('@')[1] || t.task_id).trim();
  return txt + stateSuffix(lower(t.status));
};

// ---- render ---------------------------------------------------------------
// No silent caps: when the list is trimmed the section says so, because a
// truncated list that looks complete is worse than a long one.
// Text and buttons are cut by the SAME budget, shared across both headings, so a row
// can never appear in the list without its buttons or the reverse.
const shown = [
  ...observed.map((o) => ({ id: o.taskId, text: observedLine(o) })),
  ...declared.map((t) => ({ id: String(t.task_id).trim(), text: declaredLine(t) })),
].slice(0, MAX_ITEMS);
const dropped = observed.length + declared.length - shown.length;

const blocks = [];
const seen = new Set(shown.map((s) => s.id));
const obsItems = observed.filter((o) => seen.has(o.taskId)).map(observedLine);
const decItems = declared.filter((t) => seen.has(String(t.task_id).trim())).map(declaredLine);
if (obsItems.length) blocks.push({ heading: 'Observed', items: obsItems });
if (decItems.length) blocks.push({ heading: 'Declared', items: decItems });
// No silent caps: a truncated list that looks complete is worse than a long one.
if (dropped > 0) blocks.push({ items: ['… +' + dropped + ' more, not shown and not tappable'] });

// ---- actions --------------------------------------------------------------
// EVERY shown row gets its own two buttons — each is a separate thing you either
// did or handed off, so a shared button would be a lie about which one you meant.
//
// Exactly two: the keyboard is a static fixedCollection, so the count cannot vary
// at runtime, and Telegram rejects the ENTIRE keyboard if one button is invalid.
//
// The same two verbs as the commitments plugin, and for the same reason — they are
// different claims. 'd' asserts the work is finished; 'a' hands it to an assistant
// and leaves it OPEN. Nothing acts on an assignment yet, so an assigned row keeps
// showing up at ⏳ until it is genuinely closed. That is correct, not a gap.
const actions = [];
if (ACTION_MODE === 'fix') {
  for (const row of shown) {
    const done   = 'tk|d|' + row.id;
    const assign = 'tk|a|' + row.id;
    if (done.length > CB_LIMIT || assign.length > CB_LIMIT) continue;
    actions.push({
      text: row.text.slice(0, 120),
      buttons: [
        { label: '✅ Done', cb: done },
        { label: '🤖 Assign', cb: assign },
      ],
    });
  }
}

// Always exactly one item, even with nothing to report — returning zero items is
// indistinguishable from a crash. Silence here answers a question you would
// otherwise go and check, so the section prints rather than disappearing.
return [{
  json: {
    key: 'upkeep',
    icon: '🔧',
    title: 'UPKEEP',
    blocks,
    actions,
    empty: 'Nothing outstanding',
  },
}];
